WITH metrics AS (SELECT *, ROUND(cost / SUM(cost) OVER (PARTITION BY status, carrier), 4) AS cost_share, FIRST_VALUE(cost, TRUE) OVER (PARTITION BY order_id ORDER BY cost, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS first_known_cost, MAX(cost) OVER (PARTITION BY status) AS status_max_cost FROM shipments WHERE order_id IN (9, 14, 38)) SELECT DATE_TRUNC('MONTH', shipped_date) AS activity_month, status, SUM(first_known_cost) FILTER (WHERE status = 'RETURNED') AS returned_total_first_known_cost, MAX(cost) AS max_cost, COUNT(*) AS event_count FROM metrics GROUP BY 1, 2 ORDER BY event_count DESC
